*{box-sizing:border-box} :root{--ink:#172a36;--muted:#758792;--line:#e4e9e7;--paper:#fbfcf9;--mint:#a9e3ca;--green:#4cbb91;--deep:#203c43;--mono:'DM Mono',monospace;--sans:'DM Sans',sans-serif}html,body{height:100%;margin:0;background:#e8efeb;color:var(--ink);font-family:var(--sans);overflow:hidden}body{display:grid;place-items:center}.game-shell{width:min(1120px,100vw);height:min(820px,100dvh);min-height:580px;background:var(--paper);display:flex;flex-direction:column;box-shadow:0 18px 70px #253c3620;overflow:hidden}.topbar{height:74px;display:flex;align-items:center;justify-content:space-between;padding:0 30px;border-bottom:1px solid var(--line);flex:none}.brand{display:flex;align-items:center;gap:12px}.brand-mark{width:37px;height:37px;border-radius:12px;background:#dff3e9;color:#379f7c;display:grid;place-items:center;font-size:23px}.eyebrow,.vital-label,.inventory-label,.resource-name,.world-heading,.mission-kicker,.location-tag,.zoom-button,.controls-hint,.action-button,.footer-center,footer,.modal-eyebrow,.modal-foot{font-family:var(--mono);letter-spacing:.08em}.eyebrow{font-size:9px;color:#85968e;margin-bottom:1px}.eyebrow span{color:#c3d4ca}h1{font-size:17px;margin:0;font-weight:700;letter-spacing:-.03em}.top-right{display:flex;align-items:center;gap:10px}.day-chip{height:32px;padding:0 11px;border:1px solid var(--line);border-radius:8px;display:flex;align-items:center;gap:8px;font:10px var(--mono);color:#82918b;letter-spacing:.07em}.day-chip b{color:#40554e;font-weight:500;margin-left:5px}.sun-icon{font-size:16px;color:#daa54c}.icon-button{width:31px;height:31px;border:1px solid var(--line);border-radius:8px;background:white;color:#75877f;font-size:15px;cursor:pointer}.game-area{margin:18px 30px 0;flex:1;min-height:0;display:flex;flex-direction:column}.canvas-wrap{position:relative;flex:1;min-height:260px;overflow:hidden;border-radius:12px;background:#68a69b;box-shadow:0 3px 12px #203c4312}.canvas-wrap canvas{width:100%;height:100%;display:block;image-rendering:pixelated;image-rendering:crisp-edges}.location-tag{position:absolute;left:15px;top:14px;color:#eff8ed;background:#16323cbf;padding:8px 10px;border-radius:5px;font-size:9px;display:flex;align-items:center;gap:7px;box-shadow:0 2px 6px #18342a24}.location-dot,.live-dot{height:6px;width:6px;border-radius:50%;background:#a2e8bc;display:inline-block;box-shadow:0 0 8px #95ffbd}.coordinates{border-left:1px solid #ffffff50;padding-left:8px;color:#cfdfd8}.mission-card{position:absolute;right:16px;top:14px;width:216px;background:#f9fbf2ed;border:1px solid #ffffff9e;border-radius:8px;padding:12px 14px;box-shadow:0 4px 14px #1f3a3420}.mission-kicker{font-size:8px;color:#58a981;font-weight:500;letter-spacing:.13em}.mission-kicker span{font-size:8px;margin-right:4px}.mission-title{font-size:14px;font-weight:700;margin:5px 0 3px;letter-spacing:-.02em}.mission-description{color:#72827a;font-size:10px;line-height:1.45}.mission-progress{display:flex;align-items:center;gap:9px;margin-top:9px;font:9px var(--mono);color:#668276}.progress-track{height:4px;background:#e1e9dd;border-radius:5px;flex:1;overflow:hidden}.progress-track i{height:100%;width:0;background:#69c293;display:block;transition:width .3s}.zoom-button{position:absolute;right:15px;bottom:14px;background:#16323ca8;color:white;border:1px solid #ffffff35;border-radius:5px;padding:7px 9px;font-size:13px;cursor:pointer}.zoom-button span{font-size:8px;vertical-align:2px}.toast{position:absolute;left:50%;top:20px;transform:translate(-50%,-8px);opacity:0;transition:.25s;background:#193d3b;color:white;padding:9px 14px;border-radius:20px;font-size:11px;box-shadow:0 4px 15px #1f3b3b40;pointer-events:none;white-space:nowrap}.toast.show{opacity:1;transform:translate(-50%,0)}.status-row{height:76px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;flex:none}.vitals{display:flex;gap:24px}.vital{display:flex;align-items:center;gap:8px;min-width:105px}.vital-icon{width:24px;height:24px;border-radius:7px;background:#e4f4ed;color:#54ae8a;display:grid;place-items:center;font-size:13px}.vital-icon.heart{color:#d67e79;background:#f9e9e5}.vital-icon.energy{color:#d4a84e;background:#f8f0d9}.vital-copy{width:72px}.vital-label{font-size:8px;color:#899890;margin-bottom:5px;white-space:nowrap}.meter{height:4px;background:#edf0eb;border-radius:4px;overflow:hidden}.meter i{height:100%;display:block;border-radius:4px}.health-fill{background:#e18b7e;width:87%}.oxygen-fill{background:#64c6a2;width:92%;transition:width .4s}.energy-fill{background:#e2bb62;width:74%}.vital-value{font:9px var(--mono);color:#819189}.world-health{width:205px}.world-heading{font-size:8px;color:#71847c;display:flex;justify-content:space-between;margin-bottom:7px}.world-heading span:last-child{color:#4bad84}.world-track{position:relative;height:5px;border-radius:5px;background:#e8eee8;overflow:hidden}.world-track i{height:100%;width:8%;background:linear-gradient(90deg,#9fd6a4,#4abb91);display:block;transition:width .5s}.world-track span{position:absolute;inset:0;background:repeating-linear-gradient(90deg,transparent 0,transparent 19%,#ffffff 19%,#ffffff 20%)}.world-caption{font-size:9px;color:#95a29b;margin-top:6px}.bottom-row{height:90px;display:flex;align-items:center;justify-content:space-between;flex:none}.inventory-bar{display:flex;align-items:center;gap:12px}.inventory-label{font-size:8px;color:#8b9b93;white-space:nowrap}.inventory-label span{background:#e9f1eb;border-radius:4px;padding:3px 5px;color:#638174;margin-left:4px}.resource-slots{display:flex;gap:6px}.resource-slot{width:54px;height:57px;border:1px solid #e8ede8;background:#fff;border-radius:7px;position:relative;display:flex;align-items:center;flex-direction:column;justify-content:center;cursor:pointer;padding:4px}.resource-slot.active{border-color:#9bd7bd;background:#f3fbf5}.resource-icon{font-size:18px;height:22px;display:block;line-height:21px}.crystal-icon{color:#63c9bd;text-shadow:0 0 8px #70e4d7}.seed-icon{color:#85b66c}.fiber-icon{color:#b4a475}.ore-icon{color:#88949b}.resource-count{position:absolute;top:3px;right:5px;font:9px var(--mono);color:#577367}.resource-name{font-size:7px;color:#91a099;margin-top:3px}.controls-hint{font-size:8px;color:#a1ada6;white-space:nowrap}.keycap{background:#f2f4ef;border:1px solid #e5e9e2;border-radius:3px;color:#73847b;padding:3px 4px;font-size:8px}.hint-dot{padding:0 5px;color:#c3cbc4}.action-buttons{display:flex;gap:7px}.action-button{height:38px;border-radius:6px;padding:0 12px;display:flex;align-items:center;gap:7px;cursor:pointer;font-size:9px;letter-spacing:.06em}.action-button span{font-size:15px}.action-button.secondary{border:1px solid #dfe8df;background:#fff;color:#5e786e}.action-button.primary{background:#4baf87;color:white;border:1px solid #4baf87;box-shadow:0 3px 7px #4baf8727}.action-button small{font-size:8px;border-left:1px solid #ffffff66;padding-left:7px;opacity:.8}.mobile-controls{display:none}footer{height:36px;border-top:1px solid var(--line);padding:0 30px;flex:none;display:flex;align-items:center;justify-content:space-between;color:#91a097;font-size:8px;letter-spacing:.05em}footer .live-dot{width:5px;height:5px;margin-right:5px}footer button{border:0;background:none;color:#73847b;font:8px var(--mono);cursor:pointer;letter-spacing:.07em}.footer-center{font-size:8px;color:#b1bdb5}.modal-backdrop{position:fixed;inset:0;z-index:10;background:#142b2ab3;display:none;place-items:center;padding:18px}.modal-backdrop.open{display:grid}.modal{width:min(460px,100%);background:#fbfcf8;border-radius:12px;padding:27px;position:relative;box-shadow:0 20px 70px #12292355}.modal-close{position:absolute;right:16px;top:12px;border:0;background:none;font-size:24px;color:#8a9990;cursor:pointer}.modal-eyebrow{font-size:9px;color:#53aa84;letter-spacing:.14em}.modal h2{margin:6px 0 4px;font-size:23px;letter-spacing:-.04em}.modal-intro{font-size:12px;color:#7a8981;margin:0 0 20px}.recipe-list{display:grid;gap:9px}.recipe{border:1px solid #e5ebe4;background:#fff;border-radius:8px;padding:13px;display:flex;align-items:center;justify-content:space-between}.recipe-title{font-size:12px;font-weight:700}.recipe-needs{font:9px var(--mono);color:#89988f;margin-top:5px}.recipe button{border:0;border-radius:5px;background:#4baf87;color:white;padding:9px 12px;font:9px var(--mono);letter-spacing:.05em;cursor:pointer}.recipe button:disabled{background:#e6ebe7;color:#9aa59f;cursor:default}.modal-foot{margin-top:18px;padding-top:13px;border-top:1px solid #e8ece6;font-size:8px;color:#96a49b;line-height:1.6}.modal-foot b{color:#536b60}.help-pop{display:none;position:fixed;right:max(22px,calc((100vw - 1120px)/2 + 25px));top:70px;z-index:12;width:275px;background:#fbfcf8;padding:17px;border-radius:9px;box-shadow:0 8px 30px #1b302e35;font-size:12px;line-height:1.6;color:#677971}.help-pop.open{display:block}.help-pop b{color:#2c473d}.help-pop p{margin:5px 0 13px}.help-pop button{border:0;background:none;color:#429b78;padding:0;font:9px var(--mono);cursor:pointer;letter-spacing:.1em}
@media(max-width:700px){html,body{background:#13262e}.game-shell{width:100vw;height:100dvh;min-height:0;box-shadow:none}.topbar{height:58px;padding:0 15px}.brand-mark{width:32px;height:32px}.brand{gap:9px}.eyebrow{font-size:8px}h1{font-size:15px}.day-chip{font-size:9px;padding:0 8px}.icon-button{width:29px;height:29px}.game-area{margin:10px 10px 0;flex:1}.canvas-wrap{flex:1;min-height:0;border-radius:9px}.mission-card{right:9px;top:9px;width:170px;padding:9px 10px}.mission-kicker{font-size:7px}.mission-title{font-size:12px;margin:3px 0}.mission-description{font-size:9px}.mission-progress{margin-top:7px}.location-tag{left:9px;top:9px;font-size:8px;padding:7px}.coordinates{display:none}.zoom-button{right:9px;bottom:9px;padding:6px}.status-row{height:64px}.vitals{gap:9px}.vital{min-width:0;gap:5px}.vital-icon{width:21px;height:21px;font-size:11px}.vital-copy{width:52px}.vital-label{font-size:7px}.vital-value{display:none}.energy-vital{display:none}.world-health{width:105px}.world-heading{font-size:7px}.world-caption{font-size:8px}.bottom-row{height:72px;justify-content:space-between}.inventory-bar{gap:5px}.inventory-label{display:none}.resource-slots{gap:4px}.resource-slot{width:43px;height:49px}.resource-icon{font-size:16px}.resource-name{font-size:6px}.controls-hint{display:none}.action-buttons{gap:5px}.action-button{height:35px;padding:0 9px;font-size:8px}.action-button span{font-size:13px}.action-button small{display:none}footer{height:29px;padding:0 13px;font-size:7px}.footer-center{display:none}.mobile-controls{position:absolute;bottom:56px;left:15px;right:15px;display:flex;align-items:flex-end;justify-content:space-between;pointer-events:none}.joystick{width:94px;height:94px;border:1px solid #ffffff60;background:#162e3b59;border-radius:50%;position:relative;pointer-events:auto;touch-action:none}.joystick:before{content:'';position:absolute;left:50%;top:50%;width:4px;height:4px;border-radius:50%;background:#d9ece2;transform:translate(-50%,-50%)}.joystick-knob{position:absolute;width:37px;height:37px;left:28px;top:28px;border-radius:50%;background:#e5f3e8b8;border:1px solid #ffffffa6;box-shadow:0 2px 7px #18332f50}.mobile-action{pointer-events:auto;width:52px;height:52px;border-radius:50%;border:1px solid #ffffff8a;background:#eff8ecdf;color:#317c65;font-size:18px;box-shadow:0 3px 10px #142b2c33;display:flex;align-items:center;justify-content:center;position:absolute;right:5px;bottom:0}.mobile-action small{position:absolute;bottom:-15px;color:white;font:7px var(--mono);letter-spacing:.08em}.interact-mobile{right:64px;bottom:19px;width:61px;height:61px;background:#5ab58be8;color:white;font-size:21px}.modal{padding:22px}.help-pop{right:12px;top:58px;width:min(275px,calc(100vw - 24px))}}
@media(max-height:520px) and (max-width:900px){.topbar{height:45px}.game-area{margin-top:6px}.status-row{height:50px}.bottom-row{height:58px}.mission-card{transform:scale(.88);transform-origin:top right}.mobile-controls{bottom:42px}.joystick{width:75px;height:75px}.joystick-knob{left:20px;top:20px}footer{height:23px}}

(() => {
  'use strict';
  const canvas = document.querySelector('#game');
  const ctx = canvas.getContext('2d', { alpha: false });
  ctx.imageSmoothingEnabled = false;
  const W = canvas.width, H = canvas.height, TILE = 16, COLS = 68, ROWS = 50;
  const el = (id) => document.getElementById(id);
  const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
  const hash = (x, y) => { let n = x * 374761393 + y * 668265263; n = (n ^ (n >>> 13)) * 1274126177; return ((n ^ (n >>> 16)) >>> 0) / 4294967295; };
  const saveKey = 'alien-island-field-log-v1';
  let saved = {}; try { saved = JSON.parse(localStorage.getItem(saveKey) || '{}'); } catch (_) {}
  const inventory = Object.assign({ crystal:0, seed:2, fiber:0, ore:0 }, saved.inventory || {});
  const player = { x:saved.x || 34*TILE, y:saved.y || 25*TILE, dir:0, walk:0 };
  const world = { fertility:saved.fertility || 0.08, oxygen:saved.oxygen || 92, time:saved.time || 0.34, zoom:1, planted:saved.planted || [], structures:saved.structures || [], gathered:saved.gathered || [] };
  let keys = new Set(), joy = {x:0,y:0}, last = performance.now(), toastTimer, selected='crystal', soundOn=true, gameTime=0;
  const nodes=[];
  function insideIsland(x,y){ const nx=(x-34)/27, ny=(y-25)/19; return nx*nx+ny*ny < 1; }
  function tileType(x,y){ if(!insideIsland(x,y)) return 0; const d=Math.hypot((x-34)/27,(y-25)/19); if(d>.88)return 1; return 2; }
  function createNodes(){
    const used=new Set(world.gathered);
    for(let y=5;y<45;y++) for(let x=6;x<62;x++){
      if(tileType(x,y)!==2 || hash(x,y)>.025) continue;
      const r=hash(x+151,y-73), type=r<.37?'crystal':r<.69?'fiber':'ore';
      const id=`${x},${y}`; if(!used.has(id)) nodes.push({x,y,type,id});
    }
    // Guarantee a welcoming first cluster near the landing beach.
    [[31,27,'crystal'],[35,29,'crystal'],[32,32,'crystal'],[38,23,'fiber'],[27,34,'fiber'],[42,29,'ore']].forEach(([x,y,type],i)=>{const id=`${x},${y}`;if(!used.has(id)&&!nodes.some(n=>n.id===id))nodes.push({x,y,type,id});});
  }
  createNodes();
  function save(){ localStorage.setItem(saveKey,JSON.stringify({inventory,x:player.x,y:player.y,fertility:world.fertility,oxygen:world.oxygen,time:world.time,planted:world.planted,structures:world.structures,gathered:world.gathered})); }
  function notify(message){ const t=el('toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2100); }
  function terrainColor(x,y,type){
    const n=hash(x,y);
    if(type===0){const wave=Math.sin(gameTime*1.1+x*.75+y*.45)*2;return ['#427f83','#49898a','#528f8c','#39757d'][Math.floor(n*4)];}
    if(type===1)return ['#c7b98d','#d1c49a','#bdae85','#d8c99a'][Math.floor(n*4)];
    const lush=world.fertility;
    if(lush>.2 && n<lush*1.5)return ['#709c6c','#7da970','#668f66'][Math.floor(n*3)];
    return ['#7d9777','#849a78','#758d72','#899c7b'][Math.floor(n*4)];
  }
  function drawTile(x,y,tx,ty,type){
    const px=Math.floor(tx*TILE),py=Math.floor(ty*TILE);ctx.fillStyle=terrainColor(x,y,type);ctx.fillRect(px,py,TILE,TILE);
    const n=hash(x*5,y*7);
    if(type===0){
      const offset=Math.floor((gameTime*8+x*2+y*3)%17);ctx.fillStyle='#a1cfb453';ctx.fillRect(px+offset%14,py+(offset*3)%15,3,1);if(n>.92){ctx.fillStyle='#74b5a733';ctx.fillRect(px+4,py+5,4,1);}
    } else if(type===1){if(n>.5){ctx.fillStyle='#e5d6a0';ctx.fillRect(px+3,py+10,2,1);ctx.fillRect(px+11,py+4,1,1);} }
    else if(n>.72){ctx.fillStyle=world.fertility>.23?'#a4bf79':'#aab084';ctx.fillRect(px+3,py+5,1,3);ctx.fillRect(px+11,py+11,2,1);}
    if(type===2 && world.fertility>.28 && hash(x+65,y+52)<world.fertility*.055){ctx.fillStyle='#a9f3c8';ctx.globalAlpha=.5+Math.sin(gameTime*3+x)*.3;ctx.fillRect(px+6,py+6,2,2);ctx.globalAlpha=1;}
  }
  function drawPlant(px,py,kind,scale=1){
    ctx.save();ctx.translate(Math.floor(px),Math.floor(py));ctx.scale(scale,scale);
    if(kind==='tree'){
      ctx.fillStyle='#385c4d';ctx.fillRect(-2,-2,5,11);ctx.fillStyle='#426e58';ctx.fillRect(-7,-12,14,12);ctx.fillStyle='#5d9169';ctx.fillRect(-5,-15,10,7);ctx.fillStyle='#80b777';ctx.fillRect(-2,-13,4,3);ctx.fillStyle='#bfdc8a';ctx.fillRect(4,-9,2,2);
    }else if(kind==='shrub'){
      ctx.fillStyle='#416d54';ctx.fillRect(-5,-5,10,6);ctx.fillStyle='#689664';ctx.fillRect(-4,-8,7,5);ctx.fillStyle='#8fbd77';ctx.fillRect(1,-8,3,2);
    }else if(kind==='crystal'){
      ctx.shadowColor='#69eee0';ctx.shadowBlur=8;ctx.fillStyle='#3ba9a5';ctx.fillRect(-2,-10,5,12);ctx.fillStyle='#8df2de';ctx.fillRect(-1,-12,2,3);ctx.fillStyle='#297f89';ctx.fillRect(-5,-5,3,7);ctx.shadowBlur=0;
    }else if(kind==='ore'){
      ctx.fillStyle='#647880';ctx.fillRect(-6,-5,12,7);ctx.fillStyle='#9caeb0';ctx.fillRect(-4,-8,6,4);ctx.fillStyle='#455a65';ctx.fillRect(2,-4,4,5);ctx.fillStyle='#bd9e75';ctx.fillRect(-2,-4,2,2);
    }else if(kind==='flower'){
      ctx.fillStyle='#4e8d68';ctx.fillRect(-1,-3,2,6);ctx.fillStyle='#dc8fc3';ctx.fillRect(-3,-8,3,3);ctx.fillRect(1,-8,3,3);ctx.fillStyle='#f1d78d';ctx.fillRect(-1,-7,3,2);ctx.shadowColor='#eca2e2';ctx.shadowBlur=5;ctx.fillStyle='#eda6dc';ctx.fillRect(-1,-8,2,2);ctx.shadowBlur=0;
    }
    ctx.restore();
  }
  function drawStructure(s){const px=s.x*TILE+8,py=s.y*TILE+8;
    if(s.type==='beacon'){ctx.fillStyle='#385c60';ctx.fillRect(px-7,py-2,14,10);ctx.fillStyle='#6eb39a';ctx.fillRect(px-5,py-8,10,8);ctx.fillStyle='#c0f6cd';ctx.fillRect(px-2,py-12,4,5);ctx.shadowColor='#a4f5c2';ctx.shadowBlur=12;ctx.fillStyle='#b8f5c5';ctx.fillRect(px-1,py-15,2,3);ctx.shadowBlur=0;}
    else{ctx.fillStyle='#526e71';ctx.fillRect(px-8,py-5,16,11);ctx.fillStyle='#8cc6ac';ctx.fillRect(px-5,py-9,10,5);ctx.fillStyle='#a8ede1';ctx.fillRect(px-2,py-7,4,2);ctx.fillStyle='#45625e';ctx.fillRect(px-2,py+1,4,5);}
  }
  function drawPlayer(sx,sy){const bob=Math.sin(player.walk)*1.3;const x=Math.round(sx),y=Math.round(sy+bob);
    ctx.fillStyle='#233940';ctx.fillRect(x-4,y+1,9,7);ctx.fillStyle='#617d73';ctx.fillRect(x-5,y+5,4,3);ctx.fillRect(x+2,y+5,4,3);
    ctx.fillStyle='#d9e7d8';ctx.fillRect(x-4,y-8,8,9);ctx.fillStyle='#edf4dc';ctx.fillRect(x-4,y-12,8,6);ctx.fillStyle='#bbd5ca';ctx.fillRect(x-3,y-14,6,3);ctx.fillStyle='#93c5b7';ctx.fillRect(x+1,y-10,3,3);ctx.fillStyle='#e9bb73';ctx.fillRect(x+3,y-3,2,2);
    ctx.fillStyle='#f0f3db';ctx.fillRect(x-5,y-6,2,5);ctx.fillRect(x+4,y-6,2,5);
  }
  function render(){
    const scale=world.zoom, viewW=W/scale,viewH=H/scale;const camX=clamp(player.x-TILE/2-viewW/2,0,COLS*TILE-viewW),camY=clamp(player.y-TILE/2-viewH/2,0,ROWS*TILE-viewH);
    ctx.save();ctx.scale(scale,scale);ctx.translate(-camX,-camY);
    const x0=Math.floor(camX/TILE)-1,x1=Math.ceil((camX+viewW)/TILE)+1,y0=Math.floor(camY/TILE)-1,y1=Math.ceil((camY+viewH)/TILE)+1;
    for(let y=y0;y<y1;y++)for(let x=x0;x<x1;x++)drawTile(x,y,x,y,tileType(x,y));
    // scattered silhouettes establish forest depth without costly post effects
    for(let y=y0;y<y1;y++)for(let x=x0;x<x1;x++)if(tileType(x,y)===2&&hash(x+25,y-18)>.91){const kind=hash(x-11,y+38)>.65?'tree':'shrub';drawPlant(x*TILE+8,y*TILE+14,kind,.75);}
    nodes.forEach(n=>{if(n.x<x0-1||n.x>x1+1||n.y<y0-1||n.y>y1+1)return;drawPlant(n.x*TILE+8,n.y*TILE+14,n.type==='crystal'?'crystal':n.type==='ore'?'ore':'shrub');});
    world.planted.forEach(p=>{if(p.x>=x0-1&&p.x<=x1+1&&p.y>=y0-1&&p.y<=y1+1)drawPlant(p.x*TILE+8,p.y*TILE+14,'flower',p.grown?1:.7);});
    world.structures.forEach(drawStructure);
    // small alien moths wander in the revitalized canopy
    if(world.fertility>.16)for(let i=0;i<4;i++){const mx=player.x+Math.sin(gameTime*.35+i*2.7)*95+Math.sin(gameTime*.9+i)*25,my=player.y-28+Math.cos(gameTime*.4+i*3)*52;ctx.fillStyle='#d3f0b5aa';ctx.fillRect(Math.floor(mx),Math.floor(my),2,2);}
    drawPlayer(player.x,player.y);
    // Interaction halo
    const near=nearestNode();if(near&&distance(near.x*TILE+8,near.y*TILE+8,player.x,player.y)<TILE*1.5){ctx.strokeStyle='#e5f4c89c';ctx.lineWidth=1;ctx.beginPath();ctx.arc(near.x*TILE+8,near.y*TILE+8,12,0,Math.PI*2);ctx.stroke();}
    ctx.restore();
    const dayLight=(Math.sin(world.time*Math.PI*2-Math.PI/2)+1)/2;const darkness=clamp(.5-dayLight,0,.37);if(darkness>.02){ctx.fillStyle=`rgba(18,35,65,${darkness})`;ctx.fillRect(0,0,W,H);}
    if(dayLight<.22){ctx.fillStyle='rgba(102,105,181,.10)';ctx.fillRect(0,0,W,H);}
    updateHUD();
  }
  function distance(x,y,a,b){return Math.hypot(x-a,y-b)}
  function nearestNode(){let best=null,bd=Infinity;for(const n of nodes){const d=distance(n.x*TILE+8,n.y*TILE+8,player.x,player.y);if(d<bd){bd=d;best=n;}}return best;}
  function updateHUD(){
    const mins=Math.floor((world.time%1)*24*60),hr=Math.floor(mins/60),minute=mins%60;el('clock').innerHTML=`DAY ${String(Math.floor(world.time)+1).padStart(2,'0')} <b>${String(hr).padStart(2,'0')}:${String(minute).padStart(2,'0')}</b>`;
    const percent=Math.round(world.fertility*100);el('vitality-number').textContent=String(percent).padStart(2,'0')+'%';el('vitality-fill').style.width=percent+'%';el('world-caption').textContent=percent>55?'A living world, full of promise':percent>25?'Green shoots are finding their way':'A quiet world, waiting to breathe';
    el('oxygen-fill').style.width=clamp(world.oxygen,4,100)+'%';el('oxygen-value').textContent=Math.round(world.oxygen)+'%';
    ['crystal','seed','fiber','ore'].forEach(k=>el('count-'+k).textContent=inventory[k]);el('item-total').textContent=String(Object.values(inventory).reduce((a,b)=>a+b,0)).padStart(2,'0');
    const c=inventory.crystal;el('mission-progress').style.width=Math.min(100,c/3*100)+'%';el('mission-count').textContent=`${Math.min(c,3)} / 3`;
    if(c>=3&&world.structures.some(s=>s.type==='beacon')){el('mission-title').textContent='Let life take root';el('mission-description').textContent='Plant 3 alien seeds to bring the canopy back.';el('mission-progress').style.width=Math.min(100,world.planted.length/3*100)+'%';el('mission-count').textContent=`${Math.min(world.planted.length,3)} / 3`;}
    else if(c>=3){el('mission-title').textContent='Build a seed beacon';el('mission-description').textContent='Open craft and build a beacon to awaken the soil.';el('mission-progress').style.width='100%';el('mission-count').textContent='3 / 3';}
  }
  function move(dt){let dx=0,dy=0;if(keys.has('ArrowLeft')||keys.has('a'))dx--;if(keys.has('ArrowRight')||keys.has('d'))dx++;if(keys.has('ArrowUp')||keys.has('w'))dy--;if(keys.has('ArrowDown')||keys.has('s'))dy++;dx+=joy.x;dy+=joy.y;const mag=Math.hypot(dx,dy);if(mag>1){dx/=mag;dy/=mag;}if(mag>.1){const speed=52;const nx=clamp(player.x+dx*speed*dt,8,COLS*TILE-8),ny=clamp(player.y+dy*speed*dt,8,ROWS*TILE-8);if(tileType(Math.floor(nx/TILE),Math.floor(player.y/TILE))!==0)player.x=nx;if(tileType(Math.floor(player.x/TILE),Math.floor(ny/TILE))!==0)player.y=ny;player.walk+=dt*12;player.dir=Math.atan2(dy,dx);} }
  function interact(){const n=nearestNode();if(n&&distance(n.x*TILE+8,n.y*TILE+8,player.x,player.y)<TILE*1.7){inventory[n.type]++;world.gathered.push(n.id);nodes.splice(nodes.indexOf(n),1);notify(`${n.type==='crystal'?'Crystal shard':n.type==='fiber'?'Vine fiber':'Lunar ore'} collected`);save();return;}
    const plantSpot=world.planted.find(p=>distance(p.x*TILE+8,p.y*TILE+8,player.x,player.y)<TILE*1.5);if(plantSpot){plantSpot.grown=true;world.fertility=clamp(world.fertility+.02,0,1);notify('Your little seedling is growing ✦');save();return;}
    const structure=world.structures.find(s=>distance(s.x*TILE+8,s.y*TILE+8,player.x,player.y)<TILE*1.8);if(structure){if(structure.type==='purifier'){world.oxygen=100;notify('Water purified · suit oxygen restored');}else{world.fertility=clamp(world.fertility+.025,0,1);notify('Seed beacon humming · soil restored');}save();return;}
    notify('Nothing nearby — wander toward a glimmer.');
  }
  function plantSeed(){if(!inventory.seed){notify('No seeds left — gather a little more.');return;}const x=Math.floor(player.x/TILE),y=Math.floor(player.y/TILE);if(tileType(x,y)===0){notify('Find a patch of land to plant.');return;}if(world.planted.some(p=>p.x===x&&p.y===y)){notify('There is already a seedling here.');return;}inventory.seed--;world.planted.push({x,y,grown:false});world.fertility=clamp(world.fertility+.055,0,1);world.oxygen=clamp(world.oxygen+1.5,0,100);notify('A new life takes root · island vitality +5');save();}
  const recipes=[
